def minimum_to_base(apps, schema_editor):
    """Move the global minimum from the article(s) to their base (§4d)."""
    Article = apps.get_model("article", "Article")
    for base in apps.get_model("article", "ArticleBase").objects.all():
        values = [
            a.mindestbestand
            for a in Article.objects.filter(base=base)
            if a.mindestbestand is not None
        ]
        if values:
            base.mindestbestand = max(values)
            base.save()


def minimum_to_article(apps, schema_editor):
    Article = apps.get_model("article", "Article")
    for base in apps.get_model("article", "ArticleBase").objects.all():
        if base.mindestbestand is not None:
            Article.objects.filter(base=base).update(mindestbestand=base.mindestbestand)


